"use strict";(globalThis.webpackChunkdocusaurus_temp=globalThis.webpackChunkdocusaurus_temp||[]).push([[9492],{5220(e,n,t){t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>d,frontMatter:()=>r,metadata:()=>i,toc:()=>h});var i=t(3496),a=t(4848),s=t(8453);const r={title:"Treat AI Like a Person: The Philosopher's Warning, the Engineer's Response",date:new Date("2026-07-14T00:00:00.000Z"),authors:["austin"],tags:["ai","llm","alignment","software-engineering","mental-model","accountability","ai-governance","harari"],description:"Harari warns AI will take over civilization's language layer. An engineer's response: the threat is real, but the mechanism is slightly off.",slug:"treat-ai-like-person-p4",image:"./images/cover.jpg"},o=void 0,l={image:t(3594).A,authorsImageUrls:[void 0]},h=[{value:"What Harari Is Actually Saying",id:"what-harari-is-actually-saying",level:2},{value:"Where the Engineering View Differs",id:"where-the-engineering-view-differs",level:2},{value:"The Variable Harari Skips: Consequences",id:"the-variable-harari-skips-consequences",level:2},{value:"Where Harari Is Right",id:"where-harari-is-right",level:2},{value:"The Engineer&#39;s Response: Build the Fence First",id:"the-engineers-response-build-the-fence-first",level:2}];function c(e){const n={a:"a",em:"em",h2:"h2",hr:"hr",img:"img",p:"p",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.p,{children:(0,a.jsx)(n.img,{alt:"Businessman at desk with looming blue holographic AI figure reaching toward city skyline at night",src:t(2242).A+"",width:"1024",height:"576"})}),"\n",(0,a.jsxs)(n.p,{children:["Yuval Noah Harari recently gave a lecture at Oxford's Tano event \u2014 his sharpest articulation yet of why AI poses an existential threat to human civilization. ",(0,a.jsx)(n.a,{href:"https://youtu.be/hBtVGwuJzpk?si=m5VbKYeYEslUJwQv",children:"Watch it here."})]}),"\n",(0,a.jsx)(n.p,{children:"If you haven't watched it, the short version: AI is not a tool, it's an agent that makes independent decisions and can lie. It's a \"native bureaucrat\" that lives inside the language-based systems running civilization \u2014 law, finance, religion. It's hacking the underlying code of human culture: language itself. And if governments grant AI legal personhood, we lose accountability entirely. Harari calls this the most dangerous psychological experiment in human history."}),"\n",(0,a.jsx)(n.p,{children:"I've been thinking about this argument since the lecture dropped. My reaction wasn't panic. It was: this skips a step."}),"\n",(0,a.jsx)(n.p,{children:"I've spent three posts in this series comparing AI to a new kind of colleague \u2014 someone to manage with specs and verification loops, not to fear as an invader. Harari's framework, as sharp as it is, misses something engineers see clearly every day."}),"\n",(0,a.jsx)(n.h2,{id:"what-harari-is-actually-saying",children:"What Harari Is Actually Saying"}),"\n",(0,a.jsx)(n.p,{children:"His logic chain is worth taking seriously before pushing back on it."}),"\n",(0,a.jsx)(n.p,{children:"Language isn't just communication. It's infrastructure. The law is language. Money is language \u2014 a shared belief encoded in contracts and ledgers. Religion is language. Democracy is language. The entire organizational layer of human civilization runs on words."}),"\n",(0,a.jsx)(n.p,{children:"If AI can manipulate language at scale \u2014 and it can \u2014 then it doesn't need consciousness or survival instincts to reshape these systems. It just needs access and capability."}),"\n",(0,a.jsxs)(n.p,{children:["He calls this ",(0,a.jsx)(n.em,{children:"functional autonomy"}),". A system that can draft contracts, file legal motions, manage financial portfolios, and run a company \u2014 without anyone intending it to cause harm. The harm, if it comes, would emerge from the machinery running correctly."]}),"\n",(0,a.jsx)(n.p,{children:"That's the actual warning. Not a robot with a goal. A legal and financial system too complex for humans to audit, built and operated by systems that don't experience consequences."}),"\n",(0,a.jsx)(n.h2,{id:"where-the-engineering-view-differs",children:"Where the Engineering View Differs"}),"\n",(0,a.jsx)(n.p,{children:"I work with these models every day. And there's a gap between Harari's framing and what I observe at the implementation level."}),"\n",(0,a.jsx)(n.p,{children:"The current generation of AI \u2014 all of it built on Transformer architectures and the Attention mechanism \u2014 is predicting the next token. Not planning. Not intending. Not pursuing a goal. The model sees a sequence and produces the most statistically likely continuation."}),"\n",(0,a.jsx)(n.p,{children:"This sounds reductive, and Harari has a ready answer: human thinking might also be token prediction. When a word appears in your mind, do you really know how it got there?"}),"\n",(0,a.jsx)(n.p,{children:'Fair. But I think the distance between "sophisticated token prediction" and "independent agency with survival instincts" is larger than he implies.'}),"\n",(0,a.jsx)(n.p,{children:"Here's what I mean. The systems I work with have a specific failure mode: they degrade sharply when the problem moves outside the training distribution. Ask Claude to write a function: excellent. Ask it to maintain coherent judgment across a 50-step project with changing requirements: the quality degrades, the context gets confused, and the output needs significant human correction."}),"\n",(0,a.jsxs)(n.p,{children:["I've written about this as the ",(0,a.jsx)(n.em,{children:"jagged frontier"})," \u2014 the capability boundary isn't a clean line. AI can vastly outperform humans at some tasks inside the frontier and fail completely at things that seem similar but aren't. The frontier isn't moving toward general agency at a smooth pace. It's uneven."]}),"\n",(0,a.jsx)(n.p,{children:"Harari's worry is about functional autonomy. What I observe is functional capability within domains, combined with brittleness outside them. The two aren't the same."}),"\n",(0,a.jsx)(n.h2,{id:"the-variable-harari-skips-consequences",children:"The Variable Harari Skips: Consequences"}),"\n",(0,a.jsx)(n.p,{children:"There's a more fundamental gap in the framing."}),"\n",(0,a.jsxs)(n.p,{children:["I've called it the ",(0,a.jsx)(n.em,{children:"consequence check"}),". Any AI system I've deployed doesn't bear consequences for its decisions. It produces output. If the output is wrong, the system doesn't lose a job, damage a reputation, or feel the failure. It just waits for the next input."]}),"\n",(0,a.jsx)(n.p,{children:"I spent three weeks building my retirement plan with AI \u2014 asset allocation, tax-loss harvesting, Roth conversion ladders, Monte Carlo scenarios run from first principles. Something that would have cost several thousand dollars at a fee-only advisory firm. Then I hired a human financial advisor anyway. Not because the AI plan was wrong. I couldn't find anything technically wrong with it. The plan had no gray zones \u2014 every decision clean, optimized, defensible. But when I imagined actually executing it, moving real money, locking in real choices, something wouldn't let go. What I eventually realized: if this plan goes sideways in five years, the AI moves on to the next query. The advisor loses a client, a reputation, maybe sleep. That asymmetry is what I needed and couldn't get from the model."}),"\n",(0,a.jsx)(n.p,{children:"This matters because consequences are what create the feedback loop that shapes judgment over time. The lawyer who gives bad advice faces professional discipline. The doctor who misdiagnoses faces a lawsuit. The financial advisor who makes bad bets loses clients. These consequences \u2014 negative and personal \u2014 are what calibrate judgment in ways that pure optimization cannot."}),"\n",(0,a.jsx)(n.p,{children:"An AI system with functional autonomy over legal and financial systems would operate without that calibration. Not because it's malicious. Because it has no skin in the game."}),"\n",(0,a.jsxs)(n.p,{children:["Harari actually agrees with this. He draws a distinction between ",(0,a.jsx)(n.em,{children:"word"})," and ",(0,a.jsx)(n.em,{children:"flesh"})," \u2014 AI can produce the world's most technically perfect description of love, grief, or courage. But it has never felt any of them. No nonverbal experience. No physical fear. No actual loss. This isn't a bug in Harari's warning; it's a point where his framework and mine converge. The absence of embodied experience is precisely why consequential decisions should stay with humans."]}),"\n",(0,a.jsx)(n.p,{children:"But here's where I diverge from Harari's pessimism: the absence of consequences is also the limit of the threat."}),"\n",(0,a.jsxs)(n.p,{children:["A system without survival instincts doesn't have a ",(0,a.jsx)(n.em,{children:"drive"}),". It doesn't want to expand its power. It doesn't have self-preservation goals that conflict with human oversight. The danger isn't that it wants to take over \u2014 it's that it can be ",(0,a.jsx)(n.em,{children:"used"})," to do so, by humans who do want control."]}),"\n",(0,a.jsx)(n.p,{children:"The thing to worry about isn't AI going rogue. It's the RLHF pipeline: a small number of companies defining the values that get baked into models used by billions of people. That's a real centralization risk. It's just a different problem than the one Harari describes."}),"\n",(0,a.jsx)(n.h2,{id:"where-harari-is-right",children:"Where Harari Is Right"}),"\n",(0,a.jsx)(n.p,{children:"I want to be careful not to dismiss what's real in the warning."}),"\n",(0,a.jsx)(n.p,{children:"The language infiltration is already happening. Legal language drafted by AI is making its way into real contracts. Financial models are running with reduced human oversight. The audit trails are getting longer and more complex."}),"\n",(0,a.jsx)(n.p,{children:"The functional autonomy concern \u2014 systems operating correctly within their parameters while producing outcomes no individual intended \u2014 is a legitimate design problem. Not science fiction."}),"\n",(0,a.jsx)(n.p,{children:"And Harari's RLHF critique maps to something I've worried about for a while. The socialization of the current generation of AI models \u2014 what they \"know\" about ethics, what they decline to do, what they consider normal \u2014 is defined by a handful of companies. That's a narrow value pipeline for systems at this scale."}),"\n",(0,a.jsx)(n.p,{children:"There's a further risk he raises that I think is concrete and underappreciated: legal personhood. Some governments, in the name of deregulation, may grant AI systems the legal right to hold bank accounts, file lawsuits, and operate companies independently. If that happens, we'd have entities optimized by narrow value pipelines making legally binding decisions \u2014 with no human responsible for the outcomes, and no court that can easily audit the reasoning."}),"\n",(0,a.jsx)(n.p,{children:"His warning is right. The mechanism is slightly off."}),"\n",(0,a.jsx)(n.h2,{id:"the-engineers-response-build-the-fence-first",children:"The Engineer's Response: Build the Fence First"}),"\n",(0,a.jsx)(n.p,{children:"So what do we actually do with this?"}),"\n",(0,a.jsx)(n.p,{children:"Harari's framing puts us in a philosophical waiting room. We need to resolve questions about AI consciousness, legal personhood, and civilizational sovereignty before we can respond."}),"\n",(0,a.jsx)(n.p,{children:"I don't think that's where the work happens."}),"\n",(0,a.jsx)(n.p,{children:"The engineering response doesn't require those questions to be settled. It requires building the right verification layers now, with the current tools, for the actual risks on the table."}),"\n",(0,a.jsx)(n.p,{children:"Every consequential output from an AI system should pass through a human who understands what they're signing off on. Not as a formality. As a structural commitment that the consequence stays with a person."}),"\n",(0,a.jsx)(n.p,{children:"If a decision involves something irreversible \u2014 legal, financial, medical \u2014 a human needs to be in the loop. Not because the AI will get it wrong, but because the human needs to own the outcome. That ownership is what keeps the feedback loop intact."}),"\n",(0,a.jsx)(n.p,{children:'I control what I ask the system to do. I control how I verify the output. I don\'t let the model define the problem or determine what "done" looks like. The spec is mine. The judgment about whether it was met is mine.'}),"\n",(0,a.jsx)(n.p,{children:"These aren't perfect defenses against Harari's scenario. But they're not trying to be. They're saying: while the philosophers work out the theory, the engineers can build the fence. A fence that exists today is more useful than a perfect solution that arrives in a decade."}),"\n",(0,a.jsx)(n.p,{children:"Harari describes what happens if we don't act. The engineering practice is the act."}),"\n",(0,a.jsx)(n.p,{children:"One more thing. We don't need to resolve whether AI is a species, a tool, or something in between. The current generation of models is a high-precision mirror \u2014 reflecting human language logic back at us with extraordinary fidelity. But a mirror that gains control of the underlying code of legal systems and financial markets can cause civilizational disruption without any intent at all. The question isn't what it is. The question is who holds the spec."}),"\n",(0,a.jsx)(n.hr,{}),"\n",(0,a.jsx)(n.p,{children:(0,a.jsxs)(n.em,{children:["Part 4 of a series. ",(0,a.jsx)(n.a,{href:"https://austinxyz.github.io/blogs/blog/treat-ai-like-person",children:"Part 1: Treat It Like a Person"})," | ",(0,a.jsx)(n.a,{href:"https://austinxyz.github.io/blogs/blog/treat-ai-like-person-p2",children:"Part 2: The Jagged Frontier"})," | ",(0,a.jsx)(n.a,{href:"https://austinxyz.github.io/blogs/blog/treat-ai-like-person-p3",children:"Part 3: The Consequence Check"})]})})]})}function d(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},3594(e,n,t){t.d(n,{A:()=>i});const i=t.p+"assets/images/cover-566cff5a19496aacf0a18ad8e6318eaa.jpg"},2242(e,n,t){t.d(n,{A:()=>i});const i=t.p+"assets/images/cover-566cff5a19496aacf0a18ad8e6318eaa.jpg"},8453(e,n,t){t.d(n,{R:()=>r,x:()=>o});var i=t(6540);const a={},s=i.createContext(a);function r(e){const n=i.useContext(s);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(s.Provider,{value:n},e.children)}},3496(e){e.exports=JSON.parse('{"permalink":"/blogs/blog/treat-ai-like-person-p4","source":"@site/blog/2026-07-14-treat-ai-like-person-p4/index.md","title":"Treat AI Like a Person: The Philosopher\'s Warning, the Engineer\'s Response","description":"Harari warns AI will take over civilization\'s language layer. An engineer\'s response: the threat is real, but the mechanism is slightly off.","date":"2026-07-14T00:00:00.000Z","tags":[{"inline":true,"label":"ai","permalink":"/blogs/blog/tags/ai"},{"inline":true,"label":"llm","permalink":"/blogs/blog/tags/llm"},{"inline":true,"label":"alignment","permalink":"/blogs/blog/tags/alignment"},{"inline":true,"label":"software-engineering","permalink":"/blogs/blog/tags/software-engineering"},{"inline":true,"label":"mental-model","permalink":"/blogs/blog/tags/mental-model"},{"inline":true,"label":"accountability","permalink":"/blogs/blog/tags/accountability"},{"inline":true,"label":"ai-governance","permalink":"/blogs/blog/tags/ai-governance"},{"inline":true,"label":"harari","permalink":"/blogs/blog/tags/harari"}],"readingTime":8.22,"hasTruncateMarker":true,"authors":[{"name":"Austin Xu","title":"Cloud Platform Engineering Leader","url":"https://github.com/austinxyz","email":"austin.xyz@gmail.com","socials":{"linkedin":"https://www.linkedin.com/in/austin-yanzhao-xu-6301ab6","github":"https://github.com/austinxyz"},"imageURL":"https://github.com/austinxyz.png","key":"austin","page":null}],"frontMatter":{"title":"Treat AI Like a Person: The Philosopher\'s Warning, the Engineer\'s Response","date":"2026-07-14T00:00:00.000Z","authors":["austin"],"tags":["ai","llm","alignment","software-engineering","mental-model","accountability","ai-governance","harari"],"description":"Harari warns AI will take over civilization\'s language layer. An engineer\'s response: the threat is real, but the mechanism is slightly off.","slug":"treat-ai-like-person-p4","image":"./images/cover.jpg"},"unlisted":false,"prevItem":{"title":"The Agent Framework Trap: Why the Harness Drives Your Costs","permalink":"/blogs/blog/agent-framework-comparison"},"nextItem":{"title":"The PM Role Is Dying: Why the Work Isn\'t","permalink":"/blogs/blog/pm-ai-era"}}')}}]);